/* 학습 해설
 * PCM 사전 할당 축소: ENOMEM일 때만 절반 크기로 재시도
 * 오디오 시작 시 필요한 큰 DMA 버퍼를 미리 확보하면 실제 재생 준비 때 메모리 할당 실패나 지연을 줄일 수 있습니다. 원하는 최대 크기가 없더라도 작은 버퍼를 확보하는 정책을 선택할 수 있지만,모든 오류를 메모리 부족으로 보고 축소하면 잘못된 장치 설정까지 숨길 수 있습니다.
 * preallocate_pcm_pages는 do_alloc_pages 결과가 ENOMEM이 아니면 즉시 그 결과를 반환합니다. ENOMEM이면 no_fallback을 검사해 참이면 중단하고,그 외에는 size를 한 비트 오른쪽 이동해 절반으로 줄입니다. 줄인 크기가 최소16384바이트 이상인 동안 반복합니다. 모두 실패하면 dmab->bytes=0으로 표시하고 원래 요청 크기를 경고한 뒤 ENOMEM입니다.
 * 원래64KiB 요청이 계속 ENOMEM이면64,32,16KiB를 시도하고8KiB는 시도하지 않습니다. no_fallback이면64KiB 한 번입니다. 첫 결과가 EINVAL이면32KiB 재시도 없이 EINVAL입니다. do-while 구조이므로 처음부터 주어진 크기가 최소보다 작아도 첫 시도 자체는 실행됩니다.
 */
static int preallocate_pcm_pages(struct snd_pcm_substream *substream,
				 size_t size, bool no_fallback)
{
	struct snd_dma_buffer *dmab = &substream->dma_buffer;
	struct snd_card *card = substream->pcm->card;
	size_t orig_size = size;
	int err;

	do {
		err = do_alloc_pages(card, dmab->dev.type, dmab->dev.dev,
				     substream->stream, size, dmab);
		if (err != -ENOMEM)
			return err;
		if (no_fallback)
			break;
		size >>= 1;
	} while (size >= snd_minimum_buffer);
	dmab->bytes = 0; /* tell error */
	pr_warn("ALSA pcmC%dD%d%c,%d:%s: cannot preallocate for size %zu\n",
		substream->pcm->card->number, substream->pcm->device,
		substream->stream ? 'c' : 'p', substream->number,
		substream->pcm->name, orig_size);
	return -ENOMEM;
}

/**
 * snd_pcm_lib_preallocate_free - release the preallocated buffer of the specified substream.
 * @substream: the pcm substream instance
 *
 * Releases the pre-allocated buffer of the given substream.
 */

/* 학습 해설
 * PCM Prealloc Proc 변경: 새 버퍼 성공 후 이전 버퍼 교체
 * 사용자가 사전 할당 크기를 바꿀 때 기존 버퍼부터 버리면 새 크기 할당 실패로 정상 설정도 잃습니다. 새 버퍼를 먼저 확보하고 성공 후 교체하면 실패 시 기존 버퍼를 유지할 수 있습니다. 다만 교체 순간 두 버퍼가 함께 존재하므로 카드 메모리 한도에 영향이 있습니다.
 * proc write는 open_mutex를 잡고 runtime이 있으면 EBUSY입니다. 입력 줄에서10진 unsigned long을 읽어1024를 곱해 바이트로 바꾸고,0이 아닌8192 미만 또는 dma_max 초과면 EINVAL입니다. 같은 크기면 반환합니다. 새 descriptor를0 초기화하고 DMA 설정을 복사해 할당한 뒤 성공할 때만 기존 버퍼를 해제하고 새 descriptor를 대입합니다. 새 크기0이면 할당 없이 buffer_bytes_max=UINT_MAX로 둡니다.
 * 기존8MiB를16MiB로 바꿀 때 새 할당 검사 시 기존8MiB도 회계에 남아24MiB가 필요합니다. 새 할당이 실패하면 기존8MiB를 해제하지 않습니다. 최종 크기16MiB가 한도 안이어도 교체 시 순간 합계 때문에 실패할 수 있습니다. 새 할당의 음수 오류는 이 경로에서 ENOMEM으로 보고됩니다.
 */
static void snd_pcm_lib_preallocate_proc_write(struct snd_info_entry *entry,
					       struct snd_info_buffer *buffer)
{
	struct snd_pcm_substream *substream = entry->private_data;
	struct snd_card *card = substream->pcm->card;
	char line[64], str[64];
	unsigned long size;
	struct snd_dma_buffer new_dmab;

	guard(mutex)(&substream->pcm->open_mutex);
	if (substream->runtime) {
		buffer->error = -EBUSY;
		return;
	}
	if (!snd_info_get_line(buffer, line, sizeof(line))) {
		snd_info_get_str(str, line, sizeof(str));
		buffer->error = kstrtoul(str, 10, &size);
		if (buffer->error != 0)
			return;
		size *= 1024;
		if ((size != 0 && size < 8192) || size > substream->dma_max) {
			buffer->error = -EINVAL;
			return;
		}
		if (substream->dma_buffer.bytes == size)
			return;

/* 학습 해설
 * PCM Managed Buffer 설정: 고정 크기와 나중 할당의 차이
 * 드라이버마다 버퍼를 직접 만들고 지우게 하면 hw_params·hw_free 호출 순서와 자원 수명을 반복 구현해야 합니다. PCM core가 이를 관리하도록 설정할 수 있으며,고정 크기를 반드시 확보할지 나중에 동적으로 할당할지도 구분해야 합니다.
 * preallocate_pages는 DMA type이 이미 설정돼 있으면 EINVAL이고 type·device를 먼저 저장합니다. size>0,max0이면 fallback 없는 사전 할당 실패를 그대로 반환합니다. max가 있으면 정책과 substream 번호 조건 아래 축소 할당을 시도하며 ENOMEM은 허용해 계속하고 다른 오류만 반환합니다. 확보한 bytes가 있으면 buffer_bytes_max에 반영하고 dma_max를 저장하며 managed 요청이면 플래그를 세웁니다.
 * size0,max0이면 버퍼를 지금 확보하지 않고 이후 동적 할당을 위한 설정만 합니다. max가 있는 정책 경로에서 ENOMEM을 무시하고0을 반환할 수도 있으므로 설정 성공과 실제 사전 버퍼 확보는 다릅니다. 관리형 API는 반환 오류를 전달하지만 기존 lib_preallocate_pages와 for_all wrapper는 void여서 내부 반환값을 전달하지 않습니다.
 */
static int preallocate_pages(struct snd_pcm_substream *substream,
			      int type, struct device *data,
			      size_t size, size_t max, bool managed)
{
	int err;

	if (snd_BUG_ON(substream->dma_buffer.dev.type))
		return -EINVAL;

	substream->dma_buffer.dev.type = type;
	substream->dma_buffer.dev.dev = data;

	if (size > 0) {
		if (!max) {
			/* no fallback, only also inform -ENOMEM */
			err = preallocate_pcm_pages(substream, size, true);
			if (err < 0)
				return err;
		} else if (preallocate_dma &&
			   substream->number < maximum_substreams) {
			err = preallocate_pcm_pages(substream, size, false);
			if (err < 0 && err != -ENOMEM)
				return err;
		}
	}

/* 학습 해설
 * PCM Runtime 할당: 큰 버퍼 재사용과 반환1의 의미
 * 오디오 설정이 바뀔 때마다 버퍼를 새로 할당하면 지연과 메모리 작업이 늘어납니다. 이미 충분히 큰 버퍼가 있으면 실제 확보 용량을 유지하고 이번 실행에 사용할 길이만 줄일 수 있습니다. 함수의 양수 반환도 오류가 아니라 버퍼 변경 여부를 알리는 값입니다.
 * malloc_pages는 runtime과 DMA type을 검사합니다. runtime의 기존 descriptor bytes가 size 이상이면 dma_bytes만 갱신하고0입니다. 부족하면 기존 runtime 버퍼 연결을 free합니다. 충분한 사전 할당 버퍼가 있으면 재사용하고,없으면 새 descriptor와 DMA 버퍼를 만듭니다. 단,사전 버퍼가 있으면서 dma_max0인 고정 크기는 확대를 ENOMEM으로 거절합니다. 최종 runtime 연결과 요청 dma_bytes를 설정하면1입니다.
 * 실제64KiB 버퍼에서 요청32KiB이면 descriptor bytes64KiB는 남고 runtime dma_bytes만32KiB가 되어 반환0입니다. 사전 버퍼를 runtime에 처음 연결하는 경우는 새 물리 할당이 없어도1을 반환할 수 있습니다. 따라서1을 새 메모리 페이지를 반드시 할당했다는 통계로 사용하면 틀립니다.
 */
int snd_pcm_lib_malloc_pages(struct snd_pcm_substream *substream, size_t size)
{
	struct snd_card *card;
	struct snd_pcm_runtime *runtime;
	struct snd_dma_buffer *dmab = NULL;

	if (PCM_RUNTIME_CHECK(substream))
		return -EINVAL;
	if (snd_BUG_ON(substream->dma_buffer.dev.type ==
		       SNDRV_DMA_TYPE_UNKNOWN))
		return -EINVAL;
	runtime = substream->runtime;
	card = substream->pcm->card;

	if (runtime->dma_buffer_p) {
		/* perphaps, we might free the large DMA memory region
		   to save some space here, but the actual solution
		   costs us less time */
		if (runtime->dma_buffer_p->bytes >= size) {
			runtime->dma_bytes = size;
			return 0;	/* ok, do not change */
		}
		snd_pcm_lib_free_pages(substream);
	}
	if (substream->dma_buffer.area != NULL &&
	    substream->dma_buffer.bytes >= size) {

/* 학습 해설
 * PCM Runtime 해제: 사전 버퍼는 남기고 연결만 끊기
 * runtime이 사용하는 버퍼가 substream의 사전 할당 버퍼일 수도 있고 runtime만을 위해 새로 만든 버퍼일 수도 있습니다. 둘을 같은 방법으로 해제하면 재사용할 사전 버퍼까지 잃거나 동적 descriptor가 누수됩니다. 포인터 소유권을 검사해 해제 범위를 정합니다.
 * free_pages는 runtime 검사 실패면 EINVAL,현재 dma_area가 NULL이면0입니다. runtime dma_buffer_p가 substream dma_buffer의 주소와 다르면 동적으로 만든 버퍼이므로 do_free_pages와 descriptor kfree를 실행합니다. 같으면 DMA 메모리는 보존합니다. 둘 다 마지막에 snd_pcm_set_runtime_buffer(NULL)로 runtime 연결을 끊고0입니다.
 * 사전 할당64KiB를 runtime이 사용하다 hw_free하면 사전64KiB는 남아 다음 설정에 재사용할 수 있습니다. 별도 동적96KiB였다면 실제96KiB와 descriptor를 반환합니다. 사전 버퍼 자체를 끝낼 때는 snd_pcm_lib_preallocate_free를 호출하며 for_all 변형은 모든 substream을 순회합니다.
 */
int snd_pcm_lib_free_pages(struct snd_pcm_substream *substream)
{
	struct snd_pcm_runtime *runtime;

	if (PCM_RUNTIME_CHECK(substream))
		return -EINVAL;
	runtime = substream->runtime;
	if (runtime->dma_area == NULL)
		return 0;
	if (runtime->dma_buffer_p != &substream->dma_buffer) {
		struct snd_card *card = substream->pcm->card;

		/* it's a newly allocated buffer.  release it now. */
		do_free_pages(card, runtime->dma_buffer_p);
		kfree(runtime->dma_buffer_p);
	}
	snd_pcm_set_runtime_buffer(substream, NULL);
	return 0;
}
EXPORT_SYMBOL(snd_pcm_lib_free_pages);

/* 학습 해설
 * 장치 Cgroup 정책: 같은 예외 목록이 허용표 또는 거부표가 되는 이유
 * 장치가 매우 많을 때 허용할 몇 개만 적는 방식과 대부분을 허용하고 금지할 몇 개만 적는 방식은 비용이 다릅니다. 기본 정책과 예외 목록을 나누면 두 경우를 같은 자료구조로 표현할 수 있습니다. 목록에 있다는 사실만으로 허용이라고 판단하면 반대 결과를 낼 수 있습니다.
 * dev_cgroup은 css,exceptions 연결 목록,behavior를 가집니다. css_alloc은0 초기화 객체와 빈 목록을 만들고 NONE 상태입니다. online은 mutex 아래 부모가 없으면 ALLOW,부모가 있으면 예외를 복사한 뒤 성공 시 부모의 behavior를 받습니다. ALLOW 목록은 금지 예외,DENY 목록은 허용 예외입니다. offline은 NONE으로 바꾸고 css_free는 예외를 지연 해제한 뒤 객체를 해제합니다.
 * 같은 c 1:3 r 항목도 기본 ALLOW에서는 장치1:3의 읽기를 금지하고 기본 DENY에서는 그 읽기를 허용합니다. 자식은 online 시 부모 항목을 복사하므로 같은 list 노드를 공동 소유하는 것이 아닙니다. 복사 실패 때 behavior는 성공한 부모 상태로 바뀌지 않습니다. is_devcg_online은 NONE이 아닌지 검사합니다.
 */
static int devcgroup_online(struct cgroup_subsys_state *css)
{
	struct dev_cgroup *dev_cgroup = css_to_devcgroup(css);
	struct dev_cgroup *parent_dev_cgroup = css_to_devcgroup(css->parent);
	int ret = 0;

	mutex_lock(&devcgroup_mutex);

	if (parent_dev_cgroup == NULL)
		dev_cgroup->behavior = DEVCG_DEFAULT_ALLOW;
	else {
		ret = dev_exceptions_copy(&dev_cgroup->exceptions,
					  &parent_dev_cgroup->exceptions);
		if (!ret)
			dev_cgroup->behavior = parent_dev_cgroup->behavior;
	}
	mutex_unlock(&devcgroup_mutex);

	return ret;
}

static void devcgroup_offline(struct cgroup_subsys_state *css)
{
	struct dev_cgroup *dev_cgroup = css_to_devcgroup(css);

	mutex_lock(&devcgroup_mutex);

/* 학습 해설
 * 장치 예외 추가·삭제: 정확한 키 일치와 비트 합치기
 * 같은 장치에 읽기와 쓰기 규칙을 따로 쌓으면 목록 탐색 비용과 중복 해석이 늘어납니다. 종류·major·minor가 완전히 같은 항목은 권한 비트를 합칠 수 있습니다. 하지만 와일드카드와 구체 번호는 범위가 겹쳐도 같은 키가 아니므로 별도 규칙입니다.
 * add는 mutex 계약을 확인하고 먼저 kmemdup합니다. 같은 type,major,minor의 항목을 찾으면 access OR로 합치고 새 복사본을 해제합니다. 일치가 없으면 list_add_tail_rcu로 공개합니다. rm은 같은 세 필드가 정확히 일치하는 항목만 찾아 access&=~요청access를 하고,비트가0이면 list_del_rcu와 kfree_rcu합니다.
 * c 1:3 r의 access2에 w4를 추가하면6입니다. 그 뒤 r을 제거하면4가 남고 w까지 제거하면 항목을 떼어냅니다. c 1:* r 규칙은 c 1:3 r 삭제의 정확한 minor 키와 다르므로 이 helper만으로 와일드카드를 작은 범위들로 분할하지 않습니다. 이미 있는 항목을 합치는 경우도 선행 kmemdup 실패로 ENOMEM일 수 있습니다.
 */
static int dev_exception_add(struct dev_cgroup *dev_cgroup,
			     struct dev_exception_item *ex)
{
	struct dev_exception_item *excopy, *walk;

	lockdep_assert_held(&devcgroup_mutex);

	excopy = kmemdup(ex, sizeof(*ex), GFP_KERNEL);
	if (!excopy)
		return -ENOMEM;

	list_for_each_entry(walk, &dev_cgroup->exceptions, list) {
		if (walk->type != ex->type)
			continue;
		if (walk->major != ex->major)
			continue;
		if (walk->minor != ex->minor)
			continue;

		walk->access |= ex->access;
		kfree(excopy);
		excopy = NULL;
	}

	if (excopy != NULL)
		list_add_tail_rcu(&excopy->list, &dev_cgroup->exceptions);

/* 학습 해설
 * 전체 장치 매칭: 한 규칙이 요청 권한 전부를 포함해야 한다
 * 기본 거부 정책에서는 요청 범위와 권한을 확실히 허용하는 규칙이 있어야 접근을 허용할 수 있습니다. 일부만 겹치는 규칙을 허용 증거로 쓰면 허용하지 않은 장치나 쓰기까지 열릴 수 있습니다. 이 구현은 하나의 규칙이 요청 전부를 포함하는지 검사합니다.
 * match_exception은 종류 비트가 해당 항목에 포함되는지 확인합니다. 항목 major/minor가 별표가 아니면 요청 값과 같아야 합니다. access&~ex->access가0이어야 요청의 모든 권한이 항목 안에 있습니다. 그런 항목 하나를 만나면 true이고 끝까지 없으면 false입니다. 여러 노드의 접근 비트를 모으는 누적 변수가 없습니다.
 * 규칙 c 1:* rw는 c 1:3 r 요청을 포함합니다. 규칙 c 1:3 r은 요청 c 1:* r 전체를 포함하지 못합니다. c 1:* r과 c *:3 w가 따로 있는 경우 c 1:3 rw 요청은 어느 한 항목도 rw 전부를 포함하지 않으므로 이 함수는 false입니다. 동일 키의 r,w는 add에서 합쳐질 수 있지만 이 예처럼 서로 다른 키는 그 합치기 대상이 아닙니다.
 */
static bool match_exception(struct list_head *exceptions, short type,
			    u32 major, u32 minor, short access)
{
	struct dev_exception_item *ex;

	list_for_each_entry_rcu(ex, exceptions, list) {
		if ((type & DEVCG_DEV_BLOCK) && !(ex->type & DEVCG_DEV_BLOCK))
			continue;
		if ((type & DEVCG_DEV_CHAR) && !(ex->type & DEVCG_DEV_CHAR))
			continue;
		if (ex->major != ~0 && ex->major != major)
			continue;
		if (ex->minor != ~0 && ex->minor != minor)
			continue;
		/* provided access cannot have more than the exception rule */
		if (access & (~ex->access))
			continue;
		return true;
	}
	return false;
}

/**
 * match_exception_partial - iterates the exception list trying to find a partial match
 * @exceptions: list of exceptions
 * @type: device type (DEVCG_DEV_BLOCK or DEVCG_DEV_CHAR)
 * @major: device file major number, ~0 to match all
 * @minor: device file minor number, ~0 to match all
 * @access: permission mask (DEVCG_ACC_READ, DEVCG_ACC_WRITE, DEVCG_ACC_MKNOD)
 *
 * It is considered a partial match if an exception's range is found to
 * contain *any* of the devices specified by provided parameters. This is
 * used to make sure no extra access is being granted that is forbidden by
 * any of the exception list.
 *
