static ssize_t eventfd_write(struct file *file, const char __user *buf, size_t count,
			     loff_t *ppos)
{
	struct eventfd_ctx *ctx = file->private_data;
	ssize_t res;
	__u64 ucnt;

	if (count != sizeof(ucnt))
		return -EINVAL;
	if (copy_from_user(&ucnt, buf, sizeof(ucnt)))
		return -EFAULT;
	if (ucnt == ULLONG_MAX)
		return -EINVAL;
	spin_lock_irq(&ctx->wqh.lock);
	res = -EAGAIN;
	if (ULLONG_MAX - ctx->count > ucnt)
		res = sizeof(ucnt);
	else if (!(file->f_flags & O_NONBLOCK)) {
		res = wait_event_interruptible_locked_irq(ctx->wqh,
				ULLONG_MAX - ctx->count > ucnt);
		if (!res)
			res = sizeof(ucnt);
	}
	if (likely(res > 0)) {
		ctx->count += ucnt;
		current->in_eventfd = 1;

/* 학습 해설
 * Eventfd Read 실패: 사용자 복사가 실패해도 소비한 카운터는 돌아오지 않는다
 * 커널 자료를 먼저 소비하고 사용자 메모리에 전달하는 API는 전달 단계에서 실패할 수 있습니다. 함수가 오류를 반환했다고 모든 상태 변화가 취소됐다고 가정하면 알림을 중복 계산하거나 잃습니다. 카운터 소비·대기자 깨움·사용자 복사의 순서를 따로 읽어야 합니다.
