static ssize_t eventfd_read(struct kiocb *iocb, struct iov_iter *to)
{
	struct file *file = iocb->ki_filp;
	struct eventfd_ctx *ctx = file->private_data;
	__u64 ucnt = 0;

	if (iov_iter_count(to) < sizeof(ucnt))
		return -EINVAL;
	spin_lock_irq(&ctx->wqh.lock);
	if (!ctx->count) {
		if ((file->f_flags & O_NONBLOCK) ||
		    (iocb->ki_flags & IOCB_NOWAIT)) {
			spin_unlock_irq(&ctx->wqh.lock);
			return -EAGAIN;
		}

		if (wait_event_interruptible_locked_irq(ctx->wqh, ctx->count)) {
			spin_unlock_irq(&ctx->wqh.lock);
			return -ERESTARTSYS;
		}
	}
	eventfd_ctx_do_read(ctx, &ucnt);
	current->in_eventfd = 1;
	if (waitqueue_active(&ctx->wqh))
		wake_up_locked_poll(&ctx->wqh, EPOLLOUT);
	current->in_eventfd = 0;

/* 학습 해설
 * Eventfd Wait 항목 제거: EAGAIN도 제거가 완료된 결과일 수 있다
 * 커널 사용자가 eventfd 알림 연결을 끝낼 때 마지막 카운터 소비와 wait 항목 제거를 따로 하면 그 사이 다른 알림이 들어올 수 있습니다. 같은 잠금 아래 두 작업을 묶으면 마지막 관찰과 연결 해제의 순서를 맞출 수 있습니다. 반환 오류와 제거 여부를 별도로 해석해야 합니다.
 * remove_wait_queue는 IRQ 상태를 저장하고 wqh.lock 아래 do_read를 실행한 다음 wait 항목을 __remove_wait_queue로 뗍니다. 읽은 값이0이 아니고 대기자가 남으면 OUT으로 깨웁니다. 잠금을 복원한 뒤 소비값이0이면 EAGAIN,아니면0을 반환합니다. EAGAIN 분기에서도 앞의 wait 제거는 이미 실행됐습니다.
 * count0에서 호출하면 cnt0,EAGAIN이며 항목은 제거됩니다. SEMAPHORE 모드 count3이면 cnt1,count2,반환0으로 나머지 카운터를 전부 비우지는 않습니다. 일반 모드 count3이면cnt3,count0입니다. 이 helper는 read syscall처럼 값이 생길 때까지 기다리지 않습니다.
 */
int eventfd_ctx_remove_wait_queue(struct eventfd_ctx *ctx, wait_queue_entry_t *wait,
				  __u64 *cnt)
{
	unsigned long flags;

	spin_lock_irqsave(&ctx->wqh.lock, flags);
	eventfd_ctx_do_read(ctx, cnt);
	__remove_wait_queue(&ctx->wqh, wait);
	if (*cnt != 0 && waitqueue_active(&ctx->wqh))
		wake_up_locked_poll(&ctx->wqh, EPOLLOUT);
	spin_unlock_irqrestore(&ctx->wqh.lock, flags);

	return *cnt != 0 ? 0 : -EAGAIN;
}
EXPORT_SYMBOL_GPL(eventfd_ctx_remove_wait_queue);

