 * Signalfd 대기와 Poll 수명: 파일이 아닌 현재 Sighand의 큐
 * signalfd 파일은 선택 마스크를 보관하지만 실제 pending 신호와 대기열은 읽는 태스크의 신호 처리 상태에 있습니다. 따라서 파일 수명과 wait queue 수명이 같지 않을 수 있습니다. 기다릴 신호를 소비하는 순서와 queue가 사라질 때 poll 구독을 정리하는 절차가 필요합니다.
 * dequeue는 current의 siglock 아래 선택된 신호를 먼저 꺼냅니다. 없고 nonblock이면 EAGAIN입니다. blocking이면 current sighand의 queue에 등록하고 TASK_INTERRUPTIBLE 설정 뒤 다시 dequeue합니다. 신호를 얻으면 먼저 종료하고,없는데 signal_pending이면 ERESTARTSYS입니다. 그 외에는 siglock을 놓고 schedule한 뒤 다시 잡습니다. 종료 시 queue에서 제거하고 TASK_RUNNING으로 복원합니다.
 * 관심 신호와 다른 pending 신호가 함께 있으면 루프는 관심 신호 dequeue를 먼저 시도하므로 그 성공을 중단 조건보다 우선합니다. poll은 같은 current queue에 poll_wait한 뒤 siglock 아래 current pending과 shared_pending을 확인해 IN을 표시합니다. 생성 당시 태스크의 신호 queue 포인터를 ctx에 영구 저장해 두는 구조가 아닙니다.
 */
static ssize_t signalfd_dequeue(struct signalfd_ctx *ctx, kernel_siginfo_t *info,
				int nonblock)
{
	enum pid_type type;
	ssize_t ret;
	DECLARE_WAITQUEUE(wait, current);

	spin_lock_irq(&current->sighand->siglock);
	ret = dequeue_signal(&ctx->sigmask, info, &type);
	switch (ret) {
	case 0:
		if (!nonblock)
			break;
		ret = -EAGAIN;
		fallthrough;
	default:
		spin_unlock_irq(&current->sighand->siglock);
		return ret;
	}

	add_wait_queue(&current->sighand->signalfd_wqh, &wait);
	for (;;) {
		set_current_state(TASK_INTERRUPTIBLE);
		ret = dequeue_signal(&ctx->sigmask, info, &type);
		if (ret != 0)
			break;

/* 학습 해설
 * Signalfd 다중 읽기: 첫 레코드 뒤에는 기다리지 않고 부분 성공 반환
 * 여러 신호를 한 번에 읽어 syscall 비용을 줄이되,이미 한 레코드를 읽었는데 버퍼를 끝까지 채우려고 무한히 기다리면 응답이 늦어집니다. 첫 데이터를 얻은 뒤에는 현재 준비된 레코드만 더 읽고 지금까지의 성공량을 반환하는 정책이 필요합니다.
 * read_iter는 버퍼 길이를128로 나눈 몫을 레코드 한도로 사용하고0이면 EINVAL입니다. 최초 nonblock은 파일 NONBLOCK 또는 IOCB_NOWAIT입니다. dequeue 성공 후 copyinfo 성공 길이를 total에 더하고 nonblock=1로 바꿉니다. 다음 dequeue나 복사에서 실패하면 멈추며 total이 있으면 그 바이트 수,없으면 오류를 반환합니다.
 * 300바이트 목적지는 두 레코드 용량이고 남은44바이트로 세 번째를 읽지 않습니다. 첫128바이트를 성공한 뒤 다음 신호가 없으면 두 번째 dequeue는 EAGAIN이지만 최종 반환은128입니다. 두 번째 신호를 꺼낸 뒤 복사가 실패한 경우도 앞128을 반환하며,이미 꺼낸 두 번째 신호를 다시 queue에 넣는 코드는 여기 없습니다.
 */
static ssize_t signalfd_read_iter(struct kiocb *iocb, struct iov_iter *to)
{
	struct file *file = iocb->ki_filp;
	struct signalfd_ctx *ctx = file->private_data;
	size_t count = iov_iter_count(to);
	ssize_t ret, total = 0;
	kernel_siginfo_t info;
	bool nonblock;

	count /= sizeof(struct signalfd_siginfo);
	if (!count)
		return -EINVAL;

	nonblock = file->f_flags & O_NONBLOCK || iocb->ki_flags & IOCB_NOWAIT;
	do {
		ret = signalfd_dequeue(ctx, &info, nonblock);
		if (unlikely(ret <= 0))
			break;
		ret = signalfd_copyinfo(to, &info);
		if (ret < 0)
			break;
		total += ret;
		nonblock = 1;
	} while (--count);

	return total ? total: ret;

/* 학습 해설
 * Timerfd 생성·수명: Hrtimer와 Alarm 중 하나를 선택하기
 * 시간 만료를 파일의 읽기 가능 상태로 연결하면 이벤트 루프가 타이머와 다른 I/O를 함께 기다릴 수 있습니다. 일반 타이머와 시스템을 깨울 수 있는 alarm은 하부 객체와 권한 조건이 달라 같은 구조체 안에서도 어떤 종류가 활성인지 구분해야 합니다.
 * create는 MONOTONIC,REALTIME,REALTIME_ALARM,BOOTTIME,BOOTTIME_ALARM만 허용하며 다른 clock이나 생성 flags는 EINVAL입니다. 두 ALARM clock은 CAP_WAKE_ALARM 없으면 EPERM입니다. ctx를0 초기화하고 wait queue와 cancel_lock,clockid를 설정한 뒤 isalarm에 따라 union의 alarm 또는 hrtimer를 초기화합니다. moffs에 단조→실시간 오프셋을 기록하고 FD·익명 파일을 만들며 NOWAIT을 표시합니다.
 * FD 예약 실패는 ctx를 해제하고,익명 파일 생성 실패는 예약 FD를 반납한 뒤 ctx를 해제합니다. 생성만으로 만료가 설정되는 것은 아니며 초기 ticks와 interval은0입니다. timerfd_fget은 유효하지 않은 FD를 EBADF,다른 f_op를 EINVAL로 구분합니다. 같은 숫자 FD라도 다른 파일 종류이면 설정 API에 사용할 수 없습니다.
 */
SYSCALL_DEFINE2(timerfd_create, int, clockid, int, flags)
{
	int ufd;
	struct timerfd_ctx *ctx;
	struct file *file;

	/* Check the TFD_* constants for consistency.  */
	BUILD_BUG_ON(TFD_CLOEXEC != O_CLOEXEC);
	BUILD_BUG_ON(TFD_NONBLOCK != O_NONBLOCK);

	if ((flags & ~TFD_CREATE_FLAGS) ||
	    (clockid != CLOCK_MONOTONIC &&
	     clockid != CLOCK_REALTIME &&
	     clockid != CLOCK_REALTIME_ALARM &&
	     clockid != CLOCK_BOOTTIME &&
	     clockid != CLOCK_BOOTTIME_ALARM))
		return -EINVAL;

	if ((clockid == CLOCK_REALTIME_ALARM ||
	     clockid == CLOCK_BOOTTIME_ALARM) &&
	    !capable(CAP_WAKE_ALARM))
		return -EPERM;

	ctx = kzalloc(sizeof(*ctx), GFP_KERNEL);
	if (!ctx)
		return -ENOMEM;

/* 학습 해설
 * Timerfd 주기 누적: Callback은 한 번 멈추고 읽을 때 따라잡기
 * 매우 짧은 주기의 타이머를 callback에서 계속 재설정하면 사용자가 읽지 않아도 CPU가 타이머 처리에 몰릴 수 있습니다. 만료를 표시한 뒤 멈추고 사용자가 타이머에 접근할 때 지나간 주기 수를 계산하면 반복 callback 부담을 줄일 수 있습니다.
 * triggered는 wqh.lock 아래 expired=1,ticks++와 IN 깨움을 수행합니다. hrtimer와 alarm callback은 공통 helper를 호출한 뒤 각각 NORESTART입니다. periodic 재개는 read 또는 gettime에서 expired와 tintv가 있을 때 forward_now로 만료 시각을 앞으로 옮기고 restart합니다. 지나간 횟수에서1을 빼 더하는 것은 첫 callback이 이미 ticks에1을 넣었기 때문입니다.
 * 설명용 만료10ms,주기4ms,현재23ms이면 만료는10,14,18,22의4번이고 다음은26ms입니다. callback의 ticks1에 forward 결과4-1을 더하면4입니다. 이 예는 하부 해상도보다 충분히 큰 주기와 해당 시계의 현재값을 가정합니다. 나노초 시각,주기 길이,만료 횟수는 단위가 다른 값입니다.
 */
static void timerfd_triggered(struct timerfd_ctx *ctx)
{
	unsigned long flags;

	spin_lock_irqsave(&ctx->wqh.lock, flags);
	ctx->expired = 1;
	ctx->ticks++;
	wake_up_locked_poll(&ctx->wqh, EPOLLIN);
	spin_unlock_irqrestore(&ctx->wqh.lock, flags);
}

static enum hrtimer_restart timerfd_tmrproc(struct hrtimer *htmr)
{
	struct timerfd_ctx *ctx = container_of(htmr, struct timerfd_ctx,
					       t.tmr);
	timerfd_triggered(ctx);
	return HRTIMER_NORESTART;
}

static enum alarmtimer_restart timerfd_alarmproc(struct alarm *alarm,
	ktime_t now)
{
	struct timerfd_ctx *ctx = container_of(alarm, struct timerfd_ctx,
					       t.alarm);
	timerfd_triggered(ctx);
	return ALARMTIMER_NORESTART;

/* 학습 해설
 * 시계 변경 취소 등록: Realtime·절대 시각·옵션의 세 조건
 * 절대 실시간 시각으로 알람을 예약한 뒤 시스템 시각이 바뀌면 원래 의도한 마감 의미가 달라질 수 있습니다. 반면 상대 지연이나 단조 시계 타이머를 같은 방식으로 취소할 필요는 없습니다. 감시할 객체만 취소 목록에 올려 시계 변경 시 순회합니다.
 * setup_cancel은 ctx별 cancel_lock 아래 REALTIME 또는 REALTIME_ALARM이고 ABSTIME과 CANCEL_ON_SET이 모두 있는지 검사합니다. 처음 해당하면 might_cancel=true 후 전역 cancel_lock 아래 list_add_rcu합니다. 이미 등록됐으면 중복 추가하지 않습니다. 조건이 아니면 내부 remove helper가 표시를 false로 하고 list_del_rcu합니다. 별도 remove wrapper도 ctx 잠금을 사용합니다.
 * REALTIME+ABSTIME만 있으면 목록에 오르지 않습니다. MONOTONIC에 두 플래그가 있어도 이 조건은 성립하지 않습니다. CANCEL_ON_SET을 허용 flag라고 파싱했다는 사실과 그 clock에서 실제 취소 감시가 활성화됐다는 사실을 나눠야 합니다. 다시 설정하면서 조건이 사라지면 기존 등록을 제거합니다.
 */
static void timerfd_setup_cancel(struct timerfd_ctx *ctx, int flags)
{
	spin_lock(&ctx->cancel_lock);
	if ((ctx->clockid == CLOCK_REALTIME ||
	     ctx->clockid == CLOCK_REALTIME_ALARM) &&
	    (flags & TFD_TIMER_ABSTIME) && (flags & TFD_TIMER_CANCEL_ON_SET)) {
		if (!ctx->might_cancel) {
			ctx->might_cancel = true;
			spin_lock(&cancel_lock);
			list_add_rcu(&ctx->clist, &cancel_list);
			spin_unlock(&cancel_lock);
		}
	} else {
		__timerfd_remove_cancel(ctx);
	}
	spin_unlock(&ctx->cancel_lock);
}

static ktime_t timerfd_get_remaining(struct timerfd_ctx *ctx)
{
	ktime_t remaining;

	if (isalarm(ctx))
		remaining = alarm_expires_remaining(&ctx->t.alarm);
	else
		remaining = hrtimer_expires_remaining_adjusted(&ctx->t.tmr);

/* 학습 해설
 * Timerfd 시계 변경 알림: KTIME_MAX 표지와 ECANCELED 소비
 * 시계가 바뀌었다는 사건은 정상적인 만료 횟수와 다르게 사용자에게 재평가를 요구합니다. 그래도 잠든 read를 깨우려면 대기 조건이 참이 되어야 합니다. 취소 표지와 ticks 증가를 함께 사용해 깨움과 오류 전달을 연결합니다.
 * clock_was_set은 현재 단조→실시간 오프셋을 구하고 취소 목록을 RCU로 순회합니다. 등록된 ctx의 wqh.lock 아래 저장 moffs가 현재와 다르면 moffs=KTIME_MAX,ticks++ 후 IN 깨움입니다. canceled helper는 등록돼 있고 moffs가 이 표지일 때 현재 오프셋으로 되돌리고 true를 반환합니다. resume은 직접 이 순회를 하지 않고 work를 예약해 task 문맥에서 실행합니다.
 * 오프셋 변경으로 ticks가1이 되어 poll은IN일 수 있지만 이어진 read는 정상1회 만료 대신 ECANCELED를 반환하고 ticks·expired를0으로 정리합니다. 표지를 소비한 뒤에는 다음 canceled 호출이 같은 취소를 무조건 다시 true로 보고하지 않습니다. 아직 표지가 남은 상태에서 알림 경로가 반복되면 숫자가 더 증가할 수 있어 ticks만으로 시계 변경 횟수를 정확히 읽는 인터페이스가 아닙니다.
 */
void timerfd_clock_was_set(void)
{
	ktime_t moffs = ktime_mono_to_real(0);
	struct timerfd_ctx *ctx;
	unsigned long flags;

	rcu_read_lock();
	list_for_each_entry_rcu(ctx, &cancel_list, clist) {
		if (!ctx->might_cancel)
			continue;
		spin_lock_irqsave(&ctx->wqh.lock, flags);
		if (ctx->moffs != moffs) {
			ctx->moffs = KTIME_MAX;
			ctx->ticks++;
			wake_up_locked_poll(&ctx->wqh, EPOLLIN);
		}
		spin_unlock_irqrestore(&ctx->wqh.lock, flags);
	}
	rcu_read_unlock();
}

static void timerfd_resume_work(struct work_struct *work)
{
	timerfd_clock_was_set();
}

/* 학습 해설
 * Timerfd 재설정: 실행 중 Callback과 잠금 순서 맞추기
 * 타이머 설정을 덮어쓰는 동안 예전 callback이 같은 ctx를 갱신하면 새 설정과 옛 만료 상태가 섞입니다. 먼저 예전 타이머가 중단 가능한 상태인지 확인하고,실행 중이면 callback이 필요한 잠금을 놓은 채 기다려야 교착을 피합니다.
 * settime은 flag와 itimerspec 유효성을 검사하고 정확한 timerfd 파일을 얻습니다. alarm이면 권한을 다시 검사한 뒤 취소 등록을 갱신합니다. wqh.lock을 잡고 try_to_cancel이0 이상이면 그 잠금을 유지하고 진행합니다. 음수면 lock을 놓고 cancel_wait_running한 뒤 반복합니다. 이전 periodic 만료가 있으면 forward해 이전 남은 시간과 interval을 기록한 뒤 setup으로 새 설정을 적용합니다.
 * callback이 진행 중일 때 wqh.lock을 잡은 채 완료만 기다리면 callback도 같은 lock을 원할 수 있습니다. 원문은 기다리기 전에 lock을 놓습니다. setup은 expired,ticks를0으로 만들고 새 interval을 저장하며,0이 아닌 it_value만 시작합니다. ABSTIME의 시각은 timens_ktime_to_host를 거쳐 host 기준으로 바꾸고,상대 alarm은 별도 relative start를 사용합니다.
 */
static int do_timerfd_settime(int ufd, int flags, 
		const struct itimerspec64 *new,
		struct itimerspec64 *old)
{
	struct fd f;
	struct timerfd_ctx *ctx;
	int ret;

	if ((flags & ~TFD_SETTIME_FLAGS) ||
		 !itimerspec64_valid(new))
		return -EINVAL;

	ret = timerfd_fget(ufd, &f);
	if (ret)
		return ret;
	ctx = fd_file(f)->private_data;

	if (isalarm(ctx) && !capable(CAP_WAKE_ALARM)) {
		fdput(f);
		return -EPERM;
	}

	timerfd_setup_cancel(ctx, flags);

	/*
	 * We need to stop the existing timer before reprogramming
	 * it to the new values.
	 */

/* 학습 해설
 * Timerfd 읽기: 부분 사용자 복사도 양수 길이로 반환하는 경로
 * 같은64비트 카운터 파일이라도 사용자 복사 실패 처리 정책이 모두 같지는 않습니다. 최소 버퍼 길이를 검사했어도 실제 사용자 메모리에 전부 쓸 수 있다는 보장은 없습니다. 소비한 만료 횟수와 실제 복사한 바이트를 구별해야 합니다.
 * read는8바이트 미만이면 EINVAL입니다. NONBLOCK 또는 NOWAIT이면 우선 res=EAGAIN,그 외에는 ticks 조건을 interruptible wait합니다. 이어 취소면 ticks와 expired를0으로 지우고 ECANCELED입니다. ticks가 남아 있으면 지역 값에 가져오고 periodic 지연분을 더해 재무장한 뒤 ctx ticks와 expired를0으로 합니다. lock을 푼 후 copy_to_iter의 반환 바이트 수를 res로 쓰며0일 때만 EFAULT로 바꿉니다.
 * 카운터를 소비한 뒤 copy_to_iter가4를 반환하면 이 고정 구현의 read 결과도4입니다.0이면 EFAULT이지만 앞선 카운터 소비를 되돌리는 코드가 없습니다. eventfd_read가8과 다른 복사량을 모두 EFAULT로 바꾸는 것과 다릅니다. NONBLOCK에서 초기 res가 EAGAIN이어도 ticks가 준비돼 있으면 복사 결과로 바뀌어 성공합니다.
 */
static ssize_t timerfd_read_iter(struct kiocb *iocb, struct iov_iter *to)
{
	struct file *file = iocb->ki_filp;
	struct timerfd_ctx *ctx = file->private_data;
	ssize_t res;
	u64 ticks = 0;

	if (iov_iter_count(to) < sizeof(ticks))
		return -EINVAL;

	spin_lock_irq(&ctx->wqh.lock);
	if (file->f_flags & O_NONBLOCK || iocb->ki_flags & IOCB_NOWAIT)
		res = -EAGAIN;
	else
		res = wait_event_interruptible_locked_irq(ctx->wqh, ctx->ticks);

	/*
	 * If clock has changed, we do not care about the
	 * ticks and we do not rearm the timer. Userspace must
	 * reevaluate anyway.
	 */
	if (timerfd_canceled(ctx)) {
		ctx->ticks = 0;
		ctx->expired = 0;
		res = -ECANCELED;
	}

/* 학습 해설
 * Timerfd Gettime의 부수 효과: 조회도 주기 타이머를 다시 시작한다
 * 주기 타이머가 callback 뒤 멈추도록 설계됐다면 현재 남은 시간을 조회하려면 먼저 만료 시각을 현재 이후로 전진시켜야 합니다. 따라서 gettime이라는 이름이 상태를 전혀 바꾸지 않는 순수 조회를 뜻하지 않습니다.
 * gettime은 파일 검증 뒤 lock 아래 expired와 interval이 있으면 expired를0으로 만들고 forward_now-1을 ctx ticks에 더한 다음 restart합니다. 남은 시간은 alarm 또는 hrtimer helper로 얻고 음수면0으로 제한합니다. read와 달리 ticks를 소비해0으로 지우지 않습니다. 남은 value와 interval을 복사할 구조체에 넣고 잠금과 파일 참조를 놓습니다.
 * 10ms 만료·4ms 주기·현재23ms이고 callback ticks1이면 gettime은 누적 ticks를4로 보정하고 다음26ms까지 남은3ms를 보고할 수 있습니다. 이어 read는 이4를 소비할 수 있습니다. gettime 자체는 timerfd_canceled를 호출하지 않으므로 read의 취소 소비 동작까지 동일하다고 설명하면 안 됩니다.
 */
static int do_timerfd_gettime(int ufd, struct itimerspec64 *t)
{
	struct fd f;
	struct timerfd_ctx *ctx;
	int ret = timerfd_fget(ufd, &f);
	if (ret)
		return ret;
	ctx = fd_file(f)->private_data;

	spin_lock_irq(&ctx->wqh.lock);
	if (ctx->expired && ctx->tintv) {
		ctx->expired = 0;

		if (isalarm(ctx)) {
			ctx->ticks +=
				alarm_forward_now(
					&ctx->t.alarm, ctx->tintv) - 1;
			alarm_restart(&ctx->t.alarm);
		} else {
			ctx->ticks +=
				hrtimer_forward_now(&ctx->t.tmr, ctx->tintv)
				- 1;
			hrtimer_restart(&ctx->t.tmr);
		}
	}
	t->it_value = ktime_to_timespec64(timerfd_get_remaining(ctx));

/* 학습 해설
 * Timerfd 진단과 복원 Ioctl: Snapshot 범위와 취소 표지 소비
 * 체크포인트 복원은 타이머의 만료 시각뿐 아니라 아직 읽지 않은 만료 횟수도 복원할 수 있어야 합니다. 진단 출력은 관련 상태를 보여 주지만 모든 필드가 한 잠금 구간의 동일 순간 snapshot인지도 확인해야 합니다.
 * CHECKPOINT_RESTORE가 있으면 TFD_IOC_SET_TICKS는 사용자 u64를 읽고0이면 EINVAL입니다. lock 아래 canceled가 아니면 ticks를 덮어쓰고IN으로 깨우며,취소이면 ECANCELED입니다. 다른 cmd는 ENOTTY입니다. fdinfo의 value와 interval은 lock 아래 지역 변수로 복사하지만 ticks와 settime_flags는 잠금을 푼 뒤 출력 인자에서 직접 읽습니다.
 * ioctl에7을 주면 기존 ticks에7을 더하는 것이 아니라7로 대체합니다. U64 최대값도 이 함수에는 별도 거절 조건이 없습니다. 취소 표지가 있으면 canceled helper가 moffs를 현재값으로 되돌리고 ECANCELED를 내며,read 취소 분기처럼 기존 ticks·expired를0으로 지우는 코드는 이 ioctl 분기에 없습니다.
 */
static long timerfd_ioctl(struct file *file, unsigned int cmd, unsigned long arg)
{
	struct timerfd_ctx *ctx = file->private_data;
	int ret = 0;

	switch (cmd) {
	case TFD_IOC_SET_TICKS: {
		u64 ticks;

		if (copy_from_user(&ticks, (u64 __user *)arg, sizeof(ticks)))
			return -EFAULT;
		if (!ticks)
			return -EINVAL;

		spin_lock_irq(&ctx->wqh.lock);
		if (!timerfd_canceled(ctx)) {
			ctx->ticks = ticks;
			wake_up_locked_poll(&ctx->wqh, EPOLLIN);
		} else
			ret = -ECANCELED;
		spin_unlock_irq(&ctx->wqh.lock);
		break;
	}
	default:
		ret = -ENOTTY;
		break;

/* 학습 해설
 * Madvise 주소 검증: 길이 1바이트도 한 페이지로 올리는 이유
 * 가상 메모리는 페이지 단위로 관리되므로 바이트 길이를 그대로 페이지 작업 횟수로 사용할 수 없습니다. 시작 주소의 정렬과 끝 주소의 넘침까지 검사해야 요청한 범위 밖의 메모리에 작업하는 실수를 피할 수 있습니다.
 * do_madvise는 먼저 behavior 허용 여부,시작 주소의 페이지 정렬을 검사합니다. 길이는 PAGE_ALIGN으로 올림하고 입력이 0이 아닌데 결과가 0이면 EINVAL입니다. start+len이 start보다 작아지는 넘침도 EINVAL입니다. 검사를 통과해 끝과 시작이 같을 때만 0을 반환합니다. 정상 처리에서는 mmap 잠금을 잡은 후 untagged_addr_remote로 주소 태그를 제거하고 끝을 다시 계산합니다.
 * 페이지가 4096바이트인 예에서 시작 8192,길이 1은 [8192,12288) 범위입니다. 길이 4097이면 두 페이지인 8192바이트로 올림합니다. 시작 8193은 정렬되지 않아 실패합니다. 길이가 0이어도 알 수 없는 behavior나 정렬되지 않은 시작 주소가 먼저 거절되므로 항상 성공하는 호출은 아닙니다.
 */
int do_madvise(struct mm_struct *mm, unsigned long start, size_t len_in, int behavior)
{
	unsigned long end;
	int error;
	int write;
	size_t len;
	struct blk_plug plug;

	if (!madvise_behavior_valid(behavior))
		return -EINVAL;

	if (!PAGE_ALIGNED(start))
		return -EINVAL;
	len = PAGE_ALIGN(len_in);

	/* Check to see whether len was rounded up from small -ve to zero */
	if (len_in && !len)
		return -EINVAL;

	end = start + len;
	if (end < start)
		return -EINVAL;

	if (end == start)
		return 0;

/* 학습 해설
 * Madvise 잠금 선택: 읽기 잠금에서도 페이지 내용은 바뀔 수 있다
 * 잠금의 읽기·쓰기라는 이름을 사용자 데이터 읽기·쓰기와 혼동하면 메모리 회수 경로를 이해하기 어렵습니다. mmap_lock은 주소 공간의 VMA 배치와 속성을 보호하며 개별 페이지나 페이지 테이블의 모든 변경을 혼자 보호하는 잠금이 아닙니다.
 * madvise_need_mmap_write는 REMOVE,WILLNEED,DONTNEED,DONTNEED_LOCKED,COLD,PAGEOUT,FREE,POPULATE_READ,POPULATE_WRITE,COLLAPSE에 0을 반환하고 나머지에는 1을 반환합니다. do_madvise는 1이면 mmap_write_lock_killable을 사용해 중단 시 EINTR을 반환하고,0이면 mmap_read_lock을 사용합니다. 처리 후에는 선택한 모드에 맞춰 해제합니다.
 * SEQUENTIAL은 VMA의 접근 성향 flag를 바꾸므로 쓰기 잠금 경로입니다. DONTNEED는 페이지를 버리는 작업을 할 수 있지만 이 선택표에서는 읽기 잠금입니다. 따라서 읽기 잠금을 잡았다는 이유만으로 데이터가 보존된다거나 페이지 테이블이 절대로 변경되지 않는다고 결론 내리면 안 됩니다.
 */
static int madvise_need_mmap_write(int behavior)
{
	switch (behavior) {
	case MADV_REMOVE:
	case MADV_WILLNEED:
	case MADV_DONTNEED:
	case MADV_DONTNEED_LOCKED:
	case MADV_COLD:
	case MADV_PAGEOUT:
	case MADV_FREE:
	case MADV_POPULATE_READ:
	case MADV_POPULATE_WRITE:
	case MADV_COLLAPSE:
		return 0;
	default:
		/* be safe, default to 1. list exceptions explicitly */
		return 1;
	}
}

