		pmd_t orig_pmd;

/* 학습 해설
 * MADV_FREE Swap 처리: 버릴 데이터를 굳이 다시 읽지 않기
 * 프로그램이 더 이상 필요 없다고 알린 데이터가 이미 swap에 있다면 그것을 디스크에서 읽어 온 뒤 버리는 것은 낭비입니다. FREE의 swap PTE 경로는 저장된 내용을 되살리는 대신 swap 자원과 매핑 정보를 정리합니다.
 * present가 아닌 PTE에서 일반 swap entry이면 swap_pte_batch로 연속 개수를 구하고 free_swap_and_cache_nr,clear_not_present_full_ptes를 호출합니다. nr_swap에서 그 개수를 빼고 끝에서 MM_SWAPENTS 회계를 갱신합니다. hwpoison·poisoned entry는 해당 비present PTE를 지웁니다. 모든 특수 non-swap entry를 같은 방식으로 처리하는 것은 아닙니다.
 * 연속 swap PTE 3개를 정리하면 nr_swap은 0에서 -3이 되고 MM_SWAPENTS에 -3을 더해 줄입니다. 이 변수는 오류 횟수도 음수 페이지 주소도 아닙니다. 필요 없어진 내용을 swap-in하는 비용보다 나중에 새 페이지를 할당하고 0으로 채우는 편이 낫다는 것이 원문의 설명입니다.
 */
static int madvise_free_pte_range(pmd_t *pmd, unsigned long addr,
				unsigned long end, struct mm_walk *walk)

{
	const cydp_t cydp_flags = CYDP_CLEAR_YOUNG | CYDP_CLEAR_DIRTY;
	struct mmu_gather *tlb = walk->private;
	struct mm_struct *mm = tlb->mm;
	struct vm_area_struct *vma = walk->vma;
	spinlock_t *ptl;
	pte_t *start_pte, *pte, ptent;
	struct folio *folio;
	int nr_swap = 0;
	unsigned long next;
	int nr, max_nr;

	next = pmd_addr_end(addr, end);
	if (pmd_trans_huge(*pmd))
		if (madvise_free_huge_pmd(tlb, vma, pmd, addr, next))
			return 0;

	tlb_change_page_size(tlb, PAGE_SIZE);
	start_pte = pte = pte_offset_map_lock(mm, pmd, addr, &ptl);
	if (!start_pte)
		return 0;
	flush_tlb_batched_pending(mm);
